const lista = JSON.parse(fs.readFileSync(path.join(RAIZ, 'codigo', 'repos.json'), 'utf8'));
const DEST = path.join(RAIZ, 'codigo');
const token = process.env.REPOS_TOKEN || process.env.GITHUB_TOKEN || '';
const locais = {};
