fn = r"""// Reconstrói os arquivos que o Claude criou/editou DENTRO da conversa (create_file, str_replace, Write, Edit):
// versão final de cada caminho, aplicando as edições em ordem. Salvos em claude/arquivos-gerados/.
function coletarArquivos(msgs) {
  const arq = new Map();
  for (const m of msgs) for (const b of (m.content || [])) {
    if (b.type !== 'tool_use') continue;
    const i = b.input || {}, n = b.name, p = i.path || i.file_path;
    if (!p || typeof p !== 'string') continue;
    if (n === 'create_file' && typeof i.file_text === 'string') arq.set(p, i.file_text);
    else if (n === 'Write' && typeof i.content === 'string') arq.set(p, i.content);
    else if ((n === 'str_replace' || n === 'Edit') && arq.has(p)) {
      const antigo = i.old_str ?? i.old_string, novo = i.new_str ?? i.new_string;
      if (typeof antigo === 'string' && antigo && arq.get(p).includes(antigo)) arq.set(p, arq.get(p).replace(antigo, typeof novo === 'string' ? novo : ''));
    }
  }
  return arq;
}

"""
a="function converterConversas(conversas, projetoDaConversa) {"
assert a in s; s=s.replace(a, fn+a,1)
# 2) coletar após definir projeto
a="    const projeto = projetoDaConversa.get(c.uuid) || c.project?.name || null;\n"
assert a in s; s=s.replace(a, a+"    const arquivos = coletarArquivos(msgs);\n",1)
# 3) gravar arquivos e listar na nota, antes do escrever da conversa
a="    escrever(C('conversas', data.slice(0, 7)"
bloco = r"""    if (arquivos.size) {
      const base = ['arquivos-gerados', data.slice(0, 7), `${slugify(titulo, 50)}_${String(c.uuid).slice(0, 8)}`];
      corpo.push('', '---', '', '## Arquivos gerados nesta conversa', '');
      for (const [p, conteudo] of arquivos) {
        const limpo = p.replace(/^[\\/]+/, '').split(/[\\/]+/).filter(x => x && x !== '..' && x !== '.').join('/');
        if (!limpo || Buffer.byteLength(conteudo) > 8 * 1024 * 1024) continue;
        escrever(C(...base, limpo), conteudo);
        corpo.push(`- [[${['claude', ...base, limpo].join('/')}]] (${Math.round(Buffer.byteLength(conteudo) / 1024) || '<1'} KB)`);
        conta('arquivos-gerados');
      }
      corpo.push('');
    }
"""
assert a in s; s=s.replace(a, bloco+a,1)
# 4) frontmatter
a="project: projeto, messages: msgs.length,"
assert a in s; s=s.replace(a,"project: projeto, messages: msgs.length, generated_files: arquivos.size,",1)
open(p,'w',encoding='utf8').write(s); print("converter ok")
EOF
node --check scripts/converter-export.mjs && node scripts/converter-export.mjs 2>&1 | tail -2
echo "--- arquivos gerados ---"; find claude/arquivos-gerados -type f | wc -l; du -sh claude/arquivos-gerados
echo "--- radar nos arquivos gerados ---"; find claude/arquivos-gerados -type f -iname "*radar*" | head -12
echo "--- maiores ---"; find claude/arquivos-gerados -type f -printf "%s %p\n" | sort -rn | head -3 | awk '{printf "%.1f MB %s\n",$1/1048576,$2}'

